// ═══ INTERFACE HIERARCHY ═══
// Executor           → execute(Runnable)
//   └─ ExecutorService → submit(Callable/Runnable), shutdown(), invokeAll()
//       └─ ScheduledExecutorService → schedule(), scheduleAtFixedRate()
//           └─ ThreadPoolExecutor (implementation)

// ═══ execute() vs submit() ═══
ExecutorService pool = Executors.newFixedThreadPool(4);

// execute(): fire-and-forget, Runnable only, no return
pool.execute(() -> System.out.println("Trade settled"));
// If task throws → exception goes to UncaughtExceptionHandler → lost!

// submit(): returns Future, Runnable OR Callable
Future<String> future = pool.submit(() -> {
    Thread.sleep(100);
    return "SETTLED:TRD-001";
});
String result = future.get();  // blocks until done → "SETTLED:TRD-001"
// If task throws → exception captured in Future → future.get() throws ExecutionException!

// submit with Runnable: returns Future<?> (result is null)
Future<?> f2 = pool.submit((Runnable) () -> System.out.println("done"));
f2.get();  // null (Runnable has no return value)

// ═══ Future<V> — handle to pending result ═══
Future<String> future2 = pool.submit(() -> settle("TRD-001"));
future2.isDone();                    // true/false — check without blocking
future2.get();                       // blocks until result ready
future2.get(5, TimeUnit.SECONDS);   // blocks with timeout → TimeoutException
future2.cancel(true);               // attempt to cancel (mayInterrupt=true)
future2.isCancelled();              // was it cancelled?

// ═══ invokeAll — submit batch, get all results ═══
List<Callable<String>> tasks = List.of(
    () -> settle("TRD-001"),
    () -> settle("TRD-002"),
    () -> settle("TRD-003")
);
List<Future<String>> futures = pool.invokeAll(tasks);  // blocks until ALL done
for (Future<String> f : futures) {
    System.out.println(f.get());  // all guaranteed complete!
}

// ═══ invokeAny — return FIRST successful result ═══
String fastest = pool.invokeAny(tasks);  // blocks until ANY one completes
// Returns the result of the fastest task. Others may be cancelled.

// ═══ Runnable vs Callable ═══
// Runnable: void run()             — no return, no checked exception
// Callable: V call() throws Exception — returns V, throws any exception

Runnable runnable = () -> process();                    // no return
Callable<BigDecimal> callable = () -> calculateNAV();   // returns BigDecimal
```

