package com.bank.executor;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class ExecutorFrameworkTest {

    // ═══ execute() — fire and forget ═══
    @Test
    void execute_fireAndForget() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch latch = new CountDownLatch(3);

        for (int i = 0; i < 3; i++) {
            pool.execute(() -> {  // no return value!
                latch.countDown();
            });
        }
        latch.await(5, TimeUnit.SECONDS);
        assertThat(latch.getCount()).isEqualTo(0);
        pool.shutdown();
    }

    // ═══ submit(Callable) — returns Future ═══
    @Test
    void submit_callable_returnsFuture() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);

        Future<String> future = pool.submit(() -> {
            Thread.sleep(100);
            return "SETTLED:TRD-001";
        });

        assertThat(future.isDone()).isFalse();  // not yet!
        String result = future.get(5, TimeUnit.SECONDS);
        assertThat(result).isEqualTo("SETTLED:TRD-001");
        assertThat(future.isDone()).isTrue();

        pool.shutdown();
    }

    // ═══ submit captures exceptions in Future ═══
    @Test
    void submit_capturesException() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(1);

        Future<String> future = pool.submit(() -> {
            throw new RuntimeException("Settlement failed!");
        });

        assertThatThrownBy(() -> future.get())
            .isInstanceOf(ExecutionException.class)
            .hasCauseInstanceOf(RuntimeException.class)
            .hasRootCauseMessage("Settlement failed!");

        pool.shutdown();
    }

    // ═══ invokeAll — batch execution ═══
    @Test
    void invokeAll_batchExecution() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(4);

        List<Callable<BigDecimal>> navTasks = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            final int fundId = i;
            navTasks.add(() -> new BigDecimal(fundId * 1000 + 50000));
        }

        List<Future<BigDecimal>> futures = pool.invokeAll(navTasks);
        assertThat(futures).hasSize(10);

        BigDecimal totalNAV = BigDecimal.ZERO;
        for (Future<BigDecimal> f : futures) {
            assertThat(f.isDone()).isTrue();  // ALL done after invokeAll!
            totalNAV = totalNAV.add(f.get());
        }
        assertThat(totalNAV).isGreaterThan(BigDecimal.ZERO);

        pool.shutdown();
    }

    // ═══ invokeAny — first result wins ═══
    @Test
    void invokeAny_fastestWins() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(3);

        List<Callable<String>> priceSources = List.of(
            () -> { Thread.sleep(500); return "NSE:2450.00"; },
            () -> { Thread.sleep(100); return "BSE:2451.00"; },  // fastest!
            () -> { Thread.sleep(300); return "MCX:2449.00"; }
        );

        String fastest = pool.invokeAny(priceSources);
        assertThat(fastest).isEqualTo("BSE:2451.00");  // BSE responded first!

        pool.shutdown();
    }

    // ═══ Future.cancel() ═══
    @Test
    void futureCancel() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(1);

        Future<String> future = pool.submit(() -> {
            Thread.sleep(10000);
            return "done";
        });

        Thread.sleep(100);
        boolean cancelled = future.cancel(true);  // interrupt!
        assertThat(cancelled).isTrue();
        assertThat(future.isCancelled()).isTrue();

        pool.shutdown();
    }
}
